'use strict';
(()=>{
 const E=window.NBEngine,S=E.state,e=E.htmlEscape;
 const APPS=[['brief','📋','Shift Briefing'],['siem','📊','SIEM Explorer'],['endpoint','🖥️','Endpoint EDR'],['network','🌐','Network Flows'],['mail','✉️','Secure Mail'],['files','📁','Virtual Files'],['terminal','⌨️','PowerShell Console'],['linux','⌨️','Linux Shell'],['cloudcli','☁️','Cloud/Identity CLI'],['practice','🎯','Practical Missions'],['locker','🔏','Evidence Locker'],['response','🛡️','Response Console'],['recovery','🔄','Recovery Lab'],['notes','📝','Case Notebook'],['timeline','🕒','Timeline & Review'],['map','🗺️','Network Map'],['tickets','🎫','Service Desk'],['comms','📨','Incident Comms'],['eventviewer','📑','Event Viewer'],['packet','📡','Packet Inspector'],['help','💡','Guided Help'],['academy','🎓','Original Academy']];
 const names=Object.fromEntries(APPS.map(x=>[x[0],{icon:x[1],name:x[2]}]));
 const root=document.getElementById('root');
 let ui={windows:{},z:20,filter:{},selected:{},modal:'',pending:null,lockForm:{},hint:{},responseForm:{},recoveryForm:{},feedback:{},introOpen:false};
 const c=()=>E.active(),m=()=>E.current(),f=key=>ui.filter[key]||'',sel=key=>ui.selected[key]||'',setSel=(k,v)=>ui.selected[k]=v;
 const btn=(act,label,cls='',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`;
 const tagged=(val)=>`<span class="status ${e(String(val).toLowerCase())}">${e(val)}</span>`;
 const text=(value)=>e(value??'');
 const makeTable=(heads,rows)=>`<div class="datawrap"><table class="datagrid"><thead><tr>${heads.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">No matching records. Try broadening your filter or check later evidence.</td></tr>`}</tbody></table></div>`;
 const findRecord=key=>E.getRecord(key);
 const heading=(title,lead)=>`<h2 style="margin:0 0 .3rem">${title}</h2><p class="intro">${lead}</p>`;
 const notice=(s,type='')=>`<div class="notice ${type}">${s}</div>`;
 const feedback=app=>ui.feedback[app]?`<div class="notice ${ui.feedback[app].ok?'green':'red'}" role="status">${e(ui.feedback[app].message)}</div>`:'';
 const resetBtn=app=>btn('reset-tool','↻ Reset only this tool','small',`data-tool="${app}"`);
 function taskList(){let tasks=E.taskStatus(),finished=tasks.filter(x=>x.done).length;return `<div class="panel"><div class="row" style="justify-content:space-between"><strong>Practical objectives</strong><span class="pill ${finished===tasks.length?'live':''}">${finished}/${tasks.length} practised</span></div><div class="progress" aria-label="Practice progress"><span style="width:${finished/tasks.length*100}%"></span></div>${tasks.map((t,i)=>`<div class="listitem ${t.done?'task-done':''}"><div class="row"><strong>${t.done?'✓':'○'} ${i+1}. ${e(t.name)}</strong>${btn('open','Open '+e(names[t.tool]?.name||t.tool),'small',`data-app="${t.tool}"`)}</div><p>${e(t.detail)}</p></div>`).join('')}<p class="tiny muted">Completion reflects actions practised; a tutor should review the reasoning in your report.</p></div>`}
 function appBrief(){let x=c(),saved=E.taskStatus(),progress=saved.filter(t=>t.done).length;return `${heading('Your analyst shift',e(x.intro))}<div class="notice"><strong>Incident dispatch</strong><p>${e(x.briefing)}</p></div><div class="grid3" style="margin:1rem 0"><div class="metric"><b>${e(x.priority)}</b><small>Initial dispatch classification</small></div><div class="metric"><b>${E.formatTime(m().minute)}</b><small>Simulation clock</small></div><div class="metric"><b>${progress} / ${saved.length}</b><small>Practical objectives</small></div></div><div class="row" style="margin-bottom:1rem">${btn('open','📊 Open SIEM','primary',`data-app="siem"`)}${btn('open','📝 Open notes','',`data-app="notes"`)}${btn('advance','⏩ Advance clock 5 min')}${btn('reset-case','↻ Reset this case','danger small')}</div><div class="grid2"><div>${taskList()}</div><div class="panel"><h3>Organisation and service dependencies</h3>${x.assets.map(a=>`<div class="listitem"><strong>${e(a.id)}</strong> — ${e(a.name)}<p>${e(a.service)} · ${e(a.ip)} · ${tagged(E.status(a.id))}</p></div>`).join('')}<div class="highlight"><strong>Senior analyst's opening advice</strong><p class="small">${e(x.lead)}</p></div><h3 style="margin-top:1rem">Professional responsibility</h3><p class="small muted">All people, tools, hosts, IPs and evidence in this shift are fictional. In a real incident, follow your employer's policies and obtain authorisation before accessing systems or applying controls.</p></div></div>`}
 function appSiem(){let query=f('siem'),level=f('siemLevel'),logs=E.allLogs();if(query){let terms=query.toLowerCase().split(/\s+/).filter(Boolean);logs=logs.filter(l=>terms.every(t=>{let [k,...rest]=t.split(':');if(rest.length){let prop=({source:'source',asset:'asset',level:'level',id:'id',time:'time'})[k];return prop?String(l[prop]).toLowerCase().includes(rest.join(':')):JSON.stringify(l).toLowerCase().includes(t)}return JSON.stringify(l).toLowerCase().includes(t)}))}if(level)logs=logs.filter(l=>l.level===level);let record=findRecord(sel('siem'));return `${heading('SIEM event explorer','Search and correlate fictional monitoring records. Use field:value (source:identity, asset:NB-APP-02, level:high) or free text.')}<div class="toolbar"><input aria-label="SIEM search" data-filter="siem" value="${e(query)}" placeholder="Search terms or source:identity"/><select aria-label="Severity" data-filter="siemLevel"><option value="">All severities</option>${['critical','high','warning','info'].map(v=>`<option ${level===v?'selected':''} value="${v}">${v}</option>`).join('')}</select>${btn('refresh','Search','primary')}${resetBtn('siem')}</div><p class="tiny muted">${logs.length} records shown · inspect an event to log your investigative activity. Audit events from your response actions also appear here.</p>${makeTable(['Time','Source','Level','Asset','Event'],logs.map(l=>[e(l.time),e(l.source),tagged(l.level),e(l.asset),`<button class="linkbtn" data-act="inspect" data-kind="siem" data-id="${e(l.id)}">${e(l.id)} · ${e(l.text)}</button>`]))}<div class="panel" style="margin-top:.8rem">${record?`<div class="row" style="justify-content:space-between"><h3>Inspector · ${e(record.id)}</h3>${btn('flag','⚑ Flag as relevant','small',`data-id="${e(record.id)}"`)}</div><pre class="code">${e(record.content)}</pre><p class="tiny muted">Consider whether the source provides direct observation, correlation or inference.</p>`:'<h3>Event inspector</h3><p class="small muted">Open a row to inspect its raw structured fields and flag relevant evidence.</p>'}</div>${feedback('siem')}`}
 function appEndpoint(){let host=f('endpointHost')||m().host,processes=E.allProcess().filter(p=>p.asset===host);let rec=findRecord(sel('endpoint'));return `${heading('Endpoint detection & response','Inspect process ancestry, accounts and suspicious command descriptions. Stopping a process changes later process views.')}<div class="toolbar"><select aria-label="Select endpoint" data-filter="endpointHost">${c().assets.map(a=>`<option ${host===a.id?'selected':''} value="${e(a.id)}">${e(a.id)} — ${e(a.name)}</option>`).join('')}</select><span class="pill">${e(E.status(host))}</span>${resetBtn('endpoint')}</div>${makeTable(['PID','Parent PID','Process','Account','Risk / state'],processes.map(p=>[e(p.pid),e(p.parent),`<button class="linkbtn" data-act="inspect" data-kind="endpoint" data-id="${e('PROC-'+p.asset+'-'+p.pid)}">${e(p.name)}</button>`,e(p.user),p.stopped?tagged('terminated'):tagged(p.risk)]))}<div class="panel" style="margin-top:.8rem">${rec?`<h3>Selected process · ${e(rec.id)}</h3><pre class="code">${e(rec.content)}</pre>${btn('flag','⚑ Flag process','small',`data-id="${e(rec.id)}"`)}${btn('open','Open Response Console','small',`data-app="response"`)}`:'<h3>Process inspector</h3><p class="muted small">Click a process name to inspect parent-child details and command descriptions.</p>'}</div>${feedback('endpoint')}`}
 function appNetwork(){let query=f('network'),flows=E.allFlows().filter(x=>!query||JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));let record=findRecord(sel('network'));return `${heading('Network traffic analyser','Inspect fictional flow metadata. TLS egress volume is not proof of the transferred content.')}<div class="toolbar"><input aria-label="Filter network traffic" data-filter="network" value="${e(query)}" placeholder="Host, IP, port, detail…"/>${btn('refresh','Filter','primary')}${resetBtn('network')}</div>${makeTable(['Time','Source','Destination','Port','Volume','State / inspect'],flows.map(v=>[e(v.time),e(v.src),e(v.dest),e(v.port),e(v.volume),`<button class="linkbtn" data-act="inspect" data-kind="network" data-id="${e(v.id)}">${v.stopped?'BLOCKED':'ACTIVE'} · ${e(v.detail)}</button>`]))}<div class="panel" style="margin-top:.8rem">${record?`<h3>Flow inspector · ${e(record.id)}</h3><pre class="code">${e(record.content)}</pre>${btn('flag','⚑ Flag network flow','small',`data-id="${e(record.id)}"`)}`:'<h3>Flow inspector</h3><p class="small muted">Inspect a flow and compare it with endpoint and identity events. Traffic history remains visible after containment.</p>'}</div>${feedback('network')}`}
 function appMail(){let items=E.mails(),record=findRecord(sel('mail'));return `${heading('Secure communications','Open simulated messages and separate what a person reports from what technical evidence proves.')}<div class="split"><div>${items.map(msg=>`<div class="listitem"><span class="tiny muted">${e(msg.time)} · ${e(msg.from)}</span><h4>${e(msg.subject)}</h4>${btn('inspect','Open message','small',`data-kind="mail" data-id="${e(msg.id)}"`)}</div>`).join('')}</div><div class="panel">${record?`<h3>${e(record.id)}</h3><pre class="code">${e(record.content)}</pre>${btn('flag','⚑ Flag message','small',`data-id="${e(record.id)}"`)}`:'<h3>Inbox preview</h3><p class="muted">Select a message to investigate. Stakeholder messages may arrive as time advances.</p>'}</div></div>${resetBtn('mail')}${feedback('mail')}`}
 function appFiles(){let host=f('filesHost')||m().host,records=E.files().filter(v=>v.asset===host),record=findRecord(sel('files'));return `${heading('Virtual file browser','Examine inert fictional file contents—no executable code, malware or attachments are opened on your device.')}<div class="toolbar"><select data-filter="filesHost" aria-label="File-system host">${c().assets.map(a=>`<option value="${e(a.id)}" ${host===a.id?'selected':''}>${e(a.id)} — ${e(a.name)}</option>`).join('')}</select>${resetBtn('files')}</div><div class="split"><div>${records.length?records.map(v=>`<div class="listitem">📄 <button class="linkbtn" data-act="inspect" data-kind="files" data-id="${e(v.id)}">${e(v.path)}</button><p class="tiny muted">${e(v.id)} · read-only case artefact</p></div>`).join(''):'<div class="notice">No virtual files are available for this host.</div>'}</div><div class="panel">${record?`<h3>${e(record.id)}</h3><pre class="code">${e(record.content)}</pre>${btn('flag','⚑ Flag file','small',`data-id="${e(record.id)}"`)}`:'<h3>File preview</h3><p class="muted small">Select a file. Compare observed content to SIEM records and process activity.</p>'}</div></div>${feedback('files')}`}

 function appPractice(){
  const cases=window.NBSIM_LABS||{},tasks=cases[c().id]||[],m0=m();
  if(!m0.labState)m0.labState={selected:null,finished:{},notes:{},hints:{},baselines:{}};
  let st=m0.labState;
  if(!tasks.some(t=>t.id===st.selected))st.selected=tasks[0]?.id||'';
  const t=tasks.find(x=>x.id===st.selected),complete=tasks.filter(x=>st.finished[x.id]).length;
  if(!t)return heading('Practical Missions','No lab available for this scenario.');
  let level=st.hints[t.id]||0,history=m0.terminal.filter(h=>(h.session||'terminal')==='practice').slice(-9);
  let status=ui.feedback.practice;
  return `${heading('Practical Missions · Analyst Assignment Board','Investigate real-feeling tasks using simulated local systems. Type commands, open other apps, preserve records and apply controls. Tasks are independent, and answers remain hidden until you investigate.')}
   <div class="row" style="margin-bottom:.8rem;justify-content:space-between"><span class="pill live">${complete}/${tasks.length} missions completed</span><span class="small muted">${e(c().title)} · ${e(t.skill)}</span>${btn('reset-tool','↻ Reset only mission-board progress','small',`data-tool="practice"`)}</div>
   <div class="practice-grid"><aside class="practice-list panel"><h3>Investigation assignments</h3>${tasks.map((x,i)=>`<button type="button" class="practice-task ${x.id===t.id?'selected':''}" data-act="lab-select" data-id="${x.id}"><span>${st.finished[x.id]?'✓':'○'} ${i+1}. ${e(x.title)}</span><small>${e(x.skill)}</small></button>`).join('')}</aside>
   <section class="practice-main"><div class="panel"><div class="row" style="justify-content:space-between"><div><span class="upper">Assignment ${tasks.indexOf(t)+1} of ${tasks.length}</span><h3 style="font-size:1.14rem;margin:.25rem 0">${e(t.title)}</h3></div>${st.finished[t.id]?tagged('completed'):tagged('in progress')}</div><p>${e(t.brief)}</p><h4>What you must demonstrate</h4><ul class="lab-checklist">${t.checks.map(ch=>`<li>${e(ch[1])}</li>`).join('')}</ul><div class="row">${btn('lab-hint','💡 Show next hint','small')}${btn('lab-task-reset','↻ Reset only this assignment','small')}${btn('open','⌨️ Full PowerShell window','small',`data-app="terminal"`)}${btn('open','☁️ Cloud CLI window','small',`data-app="cloudcli"`)}</div>${(t.hints||[]).slice(0,level).map(h=>`<div class="hint">💡 ${e(h)}</div>`).join('')}${level>=3?`<div class="notice"><strong>Stretch task:</strong> ${e(t.stretch)}</div>`:''}</div>
   <div class="panel lab-terminal" style="margin-top:.75rem"><div class="row" style="justify-content:space-between"><h3>⌨️ Investigation terminal</h3><span class="pill">Target: ${e(m0.termHosts?.practice||m0.host)}</span></div><div class="console" id="lab-console" role="log" aria-live="polite">${history.map(h=>`<div><strong>${e(h.at)} analyst@${e(h.host)}&gt; ${e(h.cmd)}</strong><div>${e(h.output)}</div></div>`).join('')||'Analyst terminal ready. Type help or hosts. This is a local simulator, not a real operating system.'}</div><form id="lab-terminal-form" class="terminal-form"><label class="sr-only" for="lab-command">Simulated lab command</label><input id="lab-command" aria-label="Lab command" autocomplete="off" placeholder="hosts · asset FIN-WS-07 · Get-Process"/><button class="btn primary" type="submit">Run command</button></form><p class="tiny muted">You can also open the separate PowerShell, Linux and Cloud CLI windows. Their commands use the same fictional records and count towards the tasks.</p></div>
   <div class="panel" style="margin-top:.75rem"><h3>Investigation record</h3><p class="small muted">Record your interpretation when required. It is saved in your case file; automated checks verify actions rather than grading your professional judgement.</p><textarea id="lab-note" data-lab-note="${t.id}" aria-label="Investigation findings" placeholder="I observed... The evidence supports... Still unconfirmed... My next step is...">${e(st.notes[t.id]||'')}</textarea><div class="row" style="margin-top:.7rem">${btn('lab-check','✓ Check my investigation','primary')}${btn('open','🔏 Evidence Locker','small',`data-app="locker"`)}${btn('open','🛡 Response Console','small',`data-app="response"`)}</div>${status&&status.task===t.id?`<div class="notice ${status.ok?'green':'red'}" role="status">${e(status.message)}</div>`:''}</div>
   </section></div>`;
 }
 function appTerminal(which='terminal'){let hist=m().terminal.filter(h=>(h.session||'terminal')===which);const target=m().termHosts?.[which]||m().host;const names2={terminal:'PowerShell Console',linux:'Linux Shell',cloudcli:'Cloud/Identity CLI'};return `${heading(names2[which]||'Simulated terminal','Run supported investigation commands against fictional case data. Each console keeps its own target and history; no real OS action occurs.')}<div class="row"><span class="pill live">READ-ONLY SIMULATOR</span><span class="pill">Target: ${e(target)}</span>${btn('terminal-help','Command help','small')}${resetBtn(which)}</div><div class="console" id="console-${which}" role="log" aria-live="polite">${hist.map(h=>`<div><strong>${e(h.at)} soc@${e(h.host)}&gt; ${e(h.cmd)}</strong><div>${e(h.output)}</div></div>`).join('')||'Northbridge analyst terminal. Type help to begin.'}</div><form data-terminal-form="${which}" id="terminal-form-${which}" class="terminal-form"><input ${which==='terminal'?'id="terminal-input"':''} data-terminal-input="${which}" aria-label="Simulated command" placeholder="help · hosts · asset NB-LT-042 · Get-Process" autocomplete="off"/><button class="btn primary" type="submit">Run</button></form><p class="small muted">Try <code>hosts</code>, <code>asset FIN-WS-07</code>, <code>Get-Process</code>, <code>Get-WinEvent</code>, <code>Get-NetTCPConnection</code>, <code>dir</code> and <code>cat 1</code>.</p>${feedback(which)}`}
 function appLocker(){let flagged=m().flagged.filter(id=>!!findRecord(id)),existing=m().preserved;return `${heading('Digital evidence locker','Flag an artefact in another tool, then preserve a snapshot. Record purpose, handler and collection method; verify that the retained copy is unchanged.')}<div class="grid2"><div class="panel"><h3>Flagged source records</h3>${flagged.length?flagged.map(id=>`<div class="listitem"><strong>${e(id)}</strong> <span class="tiny muted">${e(findRecord(id)?.type||'')}</span><div class="row">${btn('choose-evidence','Select for preservation','small',`data-id="${e(id)}"`)}${btn('unflag','Remove flag','small',`data-id="${e(id)}"`)}</div></div>`).join(''):'<p class="small muted">No artefacts flagged. Inspect an event, process, network flow, mail or file and flag it first.</p>'}<h3>Collection / preservation</h3><div class="field"><label>Selected evidence reference</label><input id="ev-id" readonly value="${e(sel('evId'))}"/></div><div class="field"><label>Purpose of collection</label><textarea id="ev-purpose" placeholder="Why is this artefact relevant? What question will it help answer?">${e(ui.lockForm.purpose||'')}</textarea></div><div class="field"><label>Handler / collector (fictional role)</label><input id="ev-handler" value="${e(ui.lockForm.handler||'Junior SOC Analyst')}"/></div><div class="field"><label>Collection / preservation method</label><input id="ev-method" value="${e(ui.lockForm.method||'Read-only export to protected case folder')}"/></div>${btn('preserve','🔏 Preserve evidence','primary')}${resetBtn('locker')}</div><div class="panel"><h3>Preserved artefacts (${existing.length})</h3>${existing.map(p=>`<div class="listitem"><div class="row"><strong>${e(p.id)}</strong>${p.tampered?tagged('lab copy altered'):tagged('snapshot')}</div><p class="tiny">SHA-256: <code>${e(p.digest)}</code></p><p class="small">Handler: ${e(p.handler)} · ${e(p.at)}</p><div class="row">${btn('verify','Verify hash','small',`data-id="${e(p.id)}"`)}${btn('mutate','Alter LAB copy','danger small',`data-id="${e(p.id)}"`)}${btn('custody','Record custody transfer','small',`data-id="${e(p.id)}"`)}</div>${p.custody.length>1?`<p class="tiny muted">Custody transfers: ${p.custody.length-1}</p>`:''}</div>`).join('')||'<p class="small muted">No preserved evidence yet.</p>'}</div></div>${feedback('locker')}<div class="notice">Educational warning: hashing and a simulated chain-of-custody form cannot guarantee a real item's authenticity, legality or admissibility.</div>`}
 function appResponse(){let chosen=f('responseAsset')||c().assets[0].id,control=f('responseControl')||'monitor',processes=E.allProcess().filter(p=>p.asset===chosen&&!p.stopped),a=E.asset(chosen);return `${heading('Response and containment console','Apply scoped changes to the virtual organisation. Actions affect other tools. Be careful: disabling critical services can cause additional disruption.')}<div class="grid2"><div class="panel"><h3>Proposed change</h3><div class="field"><label>Affected asset</label><select data-filter="responseAsset">${c().assets.map(v=>`<option value="${e(v.id)}" ${chosen===v.id?'selected':''}>${e(v.id)} — ${e(v.name)}</option>`).join('')}</select></div><div class="notice"><strong>${e(a.name)}</strong><p>${e(a.service)} · ${e(a.ip)} · ${a.critical?'Critical service dependency':'Non-critical endpoint'}</p><p>Status: ${e(E.status(chosen))}</p></div><div class="field"><label>Response control</label><select data-filter="responseControl">${c().actions.map(v=>`<option value="${e(v)}" ${control===v?'selected':''}>${e(E.actionLabels[v])}</option>`).join('')}</select></div>${control==='kill-process'?`<div class="field"><label>Process ID</label><select id="response-pid">${processes.map(p=>`<option value="${e(p.pid)}">PID ${e(p.pid)} · ${e(p.name)} (${e(p.risk)})</option>`).join('')}</select></div>`:''}<div class="field"><label>Authorising role / named approver</label><input id="response-authority" value="${e(ui.responseForm.approved||'Incident Manager')}"/></div><div class="field"><label>Evidence-based reason, service/evidence risks and validation plan</label><textarea id="response-reason" placeholder="I propose this because event ...; impact ...; preserve ...; check ...">${e(ui.responseForm.reason||'')}</textarea></div>${btn('apply-response','Apply authorised SIMULATED control','primary')}</div><div class="panel"><h3>Operational history</h3>${m().actions.length?m().actions.slice().reverse().map(a=>`<div class="listitem"><strong>${e(a.at)} ${e(E.actionLabels[a.control])} · ${e(a.asset)}</strong><p>${e(a.outcome)}</p><p class="tiny muted">Authorised: ${e(a.approved)}</p></div>`).join(''):'<p class="muted small">No simulated actions yet.</p>'}<div class="highlight"><strong>Current simulated threat pressure</strong><p style="font-size:2rem;font-weight:850;margin:.1rem 0">${E.risk()}/100</p><p class="tiny muted">Illustrative teaching model, not a real SOC risk score.</p></div></div></div>${feedback('response')}${resetBtn('response')}`}
 function appRecovery(){let restoration=c().recovery==='restore',option=f('recoveryOption')||(restoration?'safe':'verify'),checks=['Threat access and persistence reviewed','Application and data integrity tested','Monitoring and stakeholder approval in place'];return `${heading('Recovery & service validation','Recovery is not simply turning the service back on. Test the right restoration strategy and document acceptance of residual risk.')}<div class="grid2"><div class="panel"><h3>Available recovery strategy</h3><div class="field"><label>Select strategy</label><select data-filter="recoveryOption">${restoration?'<option value="safe">Test protected 08:00 restore point in sandbox</option><option value="recent">Use unvalidated 09:45 snapshot immediately</option><option value="verify">Skip restore and only monitor</option>':'<option value="verify">Validate affected services without a full restore</option><option value="recent">Trigger unnecessary full-production restoration</option>'}</select></div><div class="notice"><strong>System context</strong><p>${restoration?'A protected 08:00 backup is available; 09:45 may contain modified files. Check before restoring.':'No evidence currently justifies a blanket production data restore. Confirm control effectiveness and service health.'}</p></div><div class="field"><label>Approval / accepting service owner</label><input id="recovery-authority" value="${e(ui.recoveryForm.approved||'Service Owner')}"/></div><div class="field"><label>Validation reasoning (minimum 15 characters)</label><textarea id="recovery-reason" placeholder="Describe the checks and why this option is safe...">${e(ui.recoveryForm.reason||'')}</textarea></div><div class="panel secondary"><h3>Validation checklist</h3>${checks.map((v,i)=>`<label class="check"><input type="checkbox" data-recovery-check="${i}" ${ui.recoveryForm['check'+i]?'checked':''}/><span>${e(v)}</span></label>`).join('')}</div>${btn('apply-recovery','Record recovery readiness','primary')}</div><div class="panel"><h3>Recovery audit trail</h3>${m().validation.length?m().validation.map(v=>`<div class="listitem"><strong>${e(v.at)} · ${e(v.choice)}</strong><p>${e(v.detail)}</p><span class="tiny muted">Approval: ${e(v.approved)}</span></div>`).join(''):'<p class="muted small">No readiness records yet.</p>'}<div class="highlight"><strong>Reminder</strong><p class="small">RTO is the target maximum time to restore a service; RPO is the acceptable data-loss window. Neither guarantees a backup is safe or clean.</p></div></div></div>${feedback('recovery')}${resetBtn('recovery')}`}
 function appNotes(){const labels={hypothesis:'Working hypothesis',impact:'Business and service impact',knowns:'Established facts (with evidence IDs)',unknowns:'Unknowns / alternatives / confidence',next:'Immediate next actions and decision authority',advisory:'Management advisory statement',improvement:'Root cause / lessons learned / measurable improvement'};return `${heading('Incident case notebook','Write real analysis, not multiple-choice answers. Your notes form part of the exported case file.')}<div class="notice green">Autosaves when you leave each field. Include evidence references and distinguish observation from inference.</div>${Object.entries(labels).map(([key,label])=>`<div class="field"><label for="journal-${key}">${e(label)}</label><textarea id="journal-${key}" data-journal="${key}" placeholder="Record your own investigation and decision-making…">${e(m().journal[key])}</textarea></div>`).join('')}<div class="row">${btn('report','Download current case file','primary')}${resetBtn('notes')}</div>${feedback('notes')}`}
 function appTimeline(){const logs=E.allLogs().map(l=>({t:l.time,label:l.id+' · '+l.text,kind:l.source})).concat(m().events.map(x=>({t:x.at,label:x.desc,kind:'learner action'}))).sort((a,b)=>a.t.localeCompare(b.t));let candidates=[...new Set([...m().flagged,...Object.values(m().inspected).flat()])].filter(x=>E.getRecord(x)),manual=m().timelineEntries||[];return `${heading('Incident timeline & debrief','Reconstruct the incident from evidence IDs and your own explanations. Separate observation from hypothesis.')}<div class="row"><span class="pill">Clock ${E.formatTime(m().minute)}</span><span class="pill ${m().late?'live':'amber'}">${m().late?'Follow-up evidence released':'Further evidence may arrive'}</span>${btn('advance','Advance 5 simulated minutes','primary')}${resetBtn('timeline')}</div><div class="grid2" style="margin:1rem 0"><div class="panel"><h3>Build your evidence timeline</h3><p class="small muted">Inspect or flag records in other tools, then add them here. The application sorts event timestamps but does not write your reasoning for you.</p><div class="field"><label>Source reference</label><select id="timeline-reference"><option value="">Choose investigated evidence…</option>${candidates.map(x=>`<option value="${e(x)}">${e(x)}</option>`).join('')}</select></div><div class="field"><label>What does this event establish? What remains uncertain?</label><textarea id="timeline-note" placeholder="At 07:46 the log shows a successful privileged sign-in; this alone does not identify the human operator…"></textarea></div>${btn('add-timeline','Add to constructed timeline','primary')}<h3 style="margin-top:1rem">Your reconstructed events</h3>${manual.length?manual.map(v=>`<div class="listitem"><strong>${e(v.time)} · ${e(v.reference)}</strong><p>${e(v.note)}</p></div>`).join(''):'<p class="muted small">No learner timeline entries yet.</p>'}</div><div class="panel"><h3>Observed case chronology</h3><div class="datawrap">${makeTable(['Time','Source','Event / action'],logs.map(x=>[e(x.t),e(x.kind),e(x.label)]))}</div></div></div>${m().late?notice('Supplementary evidence and stakeholder updates released. Check SIEM and Mail.','green'):notice('Some evidence is delayed. Continue triage or advance the clock when appropriate.')}<h3>Scenario debrief (after your attempt)</h3>${E.taskStatus().filter(x=>x.done).length>=5&&m().journal.advisory.trim().length>=40?`<details><summary>Reveal model reasoning after completing your case</summary><p>${e(c().debrief)}</p></details>`:'<div class="notice">Complete at least five practical objectives and write a management advisory note (at least 40 characters) before revealing the model debrief. You can still use Guided Help whenever you need it.</div>'}${feedback('timeline')}`}
 function appMap(){let a=c().assets,flows=E.allFlows();return `${heading('Live fictional asset map','Inspect dependencies and see the simulated effects of response controls on hosts and recorded network flows.')}<div class="grid3">${a.map(v=>`<button class="asset ${E.status(v.id).includes('DISRUPTED')?'disabled':''}" data-act="asset-info" data-id="${e(v.id)}"><span class="k">${v.kind==='workstation'?'💻':v.kind==='cloud'?'☁️':v.kind==='database'?'🗄️':'🗃️'} ${e(v.id)}</span><strong>${e(v.name)}</strong><small>${e(v.service)} · ${e(E.status(v.id))}</small></button>`).join('')}</div><h3 style="margin-top:1rem">Observed links</h3>${makeTable(['Source','Destination','Service / port','Connection'],flows.map(x=>[e(x.src),e(x.dest),e(x.port),x.stopped?tagged('blocked'):tagged('active')]))}<p class="small muted">This is a deliberately simplified network depiction, not a full topology discovery tool.</p>${feedback('map')}`}
 function appHelp(){let apps=['siem','endpoint','network','mail','files','terminal','locker','response','recovery','notes','timeline'];let tab=sel('helpTab')||'siem';let level=ui.hint[tab]||0;let tips=window.NBSIM_TIPS[tab];return `${heading('Senior analyst guidance','Ask for assistance whenever you need it. No score penalty applies for viewing hints.')}<div class="toolbar"><select id="help-tab" aria-label="Choose help topic">${apps.map(k=>`<option ${tab===k?'selected':''} value="${k}">${e(names[k].name)}</option>`).join('')}</select>${btn('next-hint','Show next tip','primary')}</div><div class="panel"><h3>${e(names[tab].name)}</h3><p>${e(tips[0])}</p>${tips.slice(1,level+1).map(v=>`<div class="hint">${e(v)}</div>`).join('')}<p class="tiny muted">Tip ${Math.min(1+level,tips.length)} of ${tips.length}</p></div><div class="panel" style="margin-top:1rem"><h3>Further references (optional online reading)</h3><p><a href="https://csrc.nist.gov/pubs/sp/800/61/r3/final" target="_blank" rel="noopener noreferrer">NIST SP 800-61 Revision 3</a></p><p><a href="https://www.ncsc.gov.uk/collection/incident-management" target="_blank" rel="noopener noreferrer">NCSC Incident Management</a></p><p><a href="https://ico.org.uk/for-organisations/report-a-breach/personal-data-breach/" target="_blank" rel="noopener noreferrer">ICO personal-data breaches</a></p></div><div class="notice">UK GDPR: a security incident is not automatically a notifiable personal-data breach. Risk-based notification rules apply. This simulated training exercise is not legal advice.</div>`}
 function appTickets(){let history=m().tickets||[],last=history.at(-1)||{};return `${heading('Incident management & service desk','Open a service ticket, assess scope/impact/urgency, assign ownership and document why you chose a priority.')}<div class="grid2"><div class="panel"><h3>${e(c().title)} · New incident record</h3><p class="small">${e(c().briefing)}</p><div class="field"><label>Classification</label><select id="ticket-class"><option value="incident" ${last.classification==='incident'?'selected':''}>Cyber security incident</option><option value="alert" ${last.classification==='alert'?'selected':''}>Unconfirmed alert under triage</option><option value="problem" ${last.classification==='problem'?'selected':''}>Underlying / recurring problem</option><option value="service request" ${last.classification==='service request'?'selected':''}>Service request</option></select></div><div class="field"><label>Business priority (organisational example, not a universal scale)</label><select id="ticket-priority">${['P1 Critical','P2 High','P3 Medium','P4 Low'].map(t=>`<option value="${e(t)}" ${last.priority===t?'selected':''}>${e(t)}</option>`).join('')}</select></div><div class="field"><label>Assigned owner</label><input id="ticket-owner" value="${e(last.owner||'Incident Manager')}"/></div><div class="field"><label>Why this classification and priority? Consider impact and urgency.</label><textarea id="ticket-reason" placeholder="State observed facts, business impact and escalation conditions…">${e(last.reason||'')}</textarea></div>${btn('save-ticket','Save incident ticket','primary')}${resetBtn('tickets')}</div><div class="panel"><h3>Recorded service desk updates</h3>${history.length?history.slice().reverse().map(t=>`<div class="listitem"><strong>${e(t.at)} · ${e(t.classification)} · ${e(t.priority)}</strong><p>Owner: ${e(t.owner)}</p><p class="small">${e(t.reason)}</p></div>`).join(''):'<p class="small muted">No ticket submitted yet. A good record identifies a named owner and specific escalation triggers.</p>'}<div class="highlight"><strong>Distinguish the processes</strong><p class="small">Incident management restores services safely; problem management investigates recurring underlying causes; change enablement provides control and approval for urgent operational changes.</p></div></div></div>${feedback('tickets')}`}
 function appComms(){let hist=m().comms||[];return `${heading('Incident command communications','Send a fictional internal or stakeholder update. The simulation checks for some unsupported certainty but cannot judge all professional nuance.')}<div class="grid2"><div class="panel"><h3>Draft stakeholder update</h3><div class="field"><label>Recipient</label><select id="comms-recipient"><option value="Incident Manager">Incident Manager</option><option value="Service Owner">Service Owner</option><option value="Executive Leadership">Executive Leadership</option><option value="Data Protection Lead">Data Protection Lead</option><option value="Customer Communications">Customer Communications</option><option value="Cloud Supplier">Cloud Supplier</option></select></div><div class="field"><label>Message (facts, impact, unknowns, planned actions, next update)</label><textarea id="comms-body" style="min-height:180px" placeholder="As at [time] we have observed... We have not yet confirmed... Actions: ... Next update: ..."></textarea></div><div class="field"><label>Approving role / responsible communicator</label><input id="comms-approval" value="Communications Lead"/></div>${btn('send-comms','Place in SIMULATED outbox','primary')}${resetBtn('comms')}</div><div class="panel"><h3>Sent simulated communications</h3>${hist.length?hist.slice().reverse().map(x=>`<div class="listitem"><strong>${e(x.at)} · ${e(x.recipient)}</strong><p class="small">${e(x.content)}</p><p class="tiny muted">Approver: ${e(x.approval)}</p><p class="${x.risk?'red':'green'} small">${e(x.warning)}</p></div>`).join(''):'<p class="muted small">No updates sent. Avoid certainty about data exposure when the investigation remains incomplete.</p>'}</div></div>${feedback('comms')}`}
 function appEventViewer(){let channel=f('evchannel')||'All channels',query=f('evquery'),rows=E.allLogs().filter(l=>{let grp=l.source==='endpoint'?'PowerShell':l.source==='identity'?'Security':l.source==='service'?'System':'Application';return(channel==='All channels'||channel===grp)&&(!query||JSON.stringify(l).toLowerCase().includes(query.toLowerCase()))}).map(l=>({...l,channel:l.source==='endpoint'?'PowerShell':l.source==='identity'?'Security':l.source==='service'?'System':'Application',eid:l.source==='identity'?(l.text.includes('rejected')||l.text.includes('unsuccessful')?'4625':'4624'):l.source==='endpoint'?'4104':l.source==='service'?'7036':'1000'}));let rec=findRecord(sel('eventviewer'));return `${heading('Windows-style Event Viewer','Simulated channels and pedagogical Event ID labels derived from the case records, not a genuine Windows event log.')}<div class="toolbar"><select aria-label="Event channel" data-filter="evchannel">${['All channels','Security','PowerShell','Application','System'].map(v=>`<option ${channel===v?'selected':''}>${v}</option>`).join('')}</select><input data-filter="evquery" value="${e(query)}" placeholder="Search event ID, asset or text"/>${btn('refresh','Filter','primary')}${resetBtn('eventviewer')}</div>${makeTable(['Time','Channel','Event ID','Asset','Record'],rows.map(l=>[e(l.time),e(l.channel),e(l.eid),e(l.asset),`<button class="linkbtn" data-act="inspect" data-kind="eventviewer" data-id="${e(l.id)}">${e(l.text)}</button>`]))}<div class="panel" style="margin-top:.8rem">${rec?`<h3>Event detail · ${e(rec.id)}</h3><pre class="code">${e(rec.content)}</pre>${btn('flag','⚑ Flag source event','small',`data-id="${e(rec.id)}"`)}`:'<p class="small muted">Open an event and correlate it in the SIEM or terminal.</p>'}</div><div class="notice">Event IDs in this practice view are illustrative where the fictional source does not include an original Windows Event ID. Always interpret provider-specific schemas in real systems.</div>`}
 function appPacket(){let flows=E.allFlows(),selected=flows.find(x=>x.id===sel('packet'));return `${heading('Packet / flow inspector','Follow a fictional network conversation and study its visible metadata. No real PCAP or live network capture is involved.')}<div class="split"><div class="panel"><h3>Captured conversations</h3>${flows.map(x=>`<div class="listitem"><div class="row"><strong>${e(x.id)} · ${e(x.time)}</strong>${tagged(x.stopped?'blocked':'observed')}</div><p class="small">${e(x.src)} → ${e(x.dest)} : ${e(x.port)} · ${e(x.volume)}</p>${btn('packet-select','Follow conversation','small',`data-id="${e(x.id)}"`)}</div>`).join('')}${resetBtn('packet')}</div><div class="panel"><h3>Protocol details</h3>${selected?`<pre class="code">Conversation: ${e(selected.id)}
Source: ${e(selected.src)}
Destination: ${e(selected.dest)}
Transport: TCP
Destination port: ${e(selected.port)}
Observation window: ${e(selected.time)}
Aggregated volume: ${e(selected.volume)}
Current simulator flow: ${e(selected.stopped?'BLOCKED':'OBSERVED')}

[SIMULATED PACKET SUMMARY]
TCP SYN   (connection initiation)
TCP SYN/ACK (response, if permitted)
TCP ACK   (connection established)
${selected.port==='443'?'TLS encrypted application data: contents not visible':'Protocol payload not reconstructed from summary metadata'}

Note: individual packet times/lengths unavailable.
A flow summary cannot prove payload content.</pre>${btn('flag','⚑ Flag observed conversation','small',`data-id="${e(selected.id)}"`)}`:'<p class="small muted">Choose one conversation. The summary intentionally does not invent detailed packet data beyond the information supplied by the case.</p>'}</div></div>${feedback('packet')}`}
 function appAcademy(){return `${heading('Original Northbridge Academy (v2)','The earlier guided lessons and investigations remain included and available as a separate local application.')}<div class="notice green"><p>Open the original Academy in a new tab to practise the foundations, its structured investigation stages and the original eight-tool workbench. It remains self-contained and uses its own browser progress key.</p></div><p><a class="btn primary" href="legacy-academy/index.html" target="_blank" rel="noopener">🎓 Launch v2 Academy</a></p><h3>Recommended sequence</h3><p>For beginners, start with the five original foundation activities, then return to the v3 desktop for an open-ended investigation. V3 is intentionally less answer-driven.</p>`}
 const renderers={brief:appBrief,siem:appSiem,endpoint:appEndpoint,network:appNetwork,mail:appMail,files:appFiles,terminal:()=>appTerminal('terminal'),linux:()=>appTerminal('linux'),cloudcli:()=>appTerminal('cloudcli'),practice:appPractice,locker:appLocker,response:appResponse,recovery:appRecovery,notes:appNotes,timeline:appTimeline,map:appMap,tickets:appTickets,comms:appComms,eventviewer:appEventViewer,packet:appPacket,help:appHelp,academy:appAcademy};
 function legal(){return `<div class="overlay" role="dialog" aria-modal="true" aria-label="Educational use agreement"><div class="welcome"><div class="upper">ESTIO · CYBER SECURITY TRAINING · NORTHBRIDGE SOC</div><img class="welcome-brand" src="assets/estio-logo.png" alt="Estio logo and coloured blocks"><h1>Welcome to the Virtual Cyber Operations Centre</h1><p><a href="knowledge/index.html" class="btn">📖 New: read the interactive Incident Response Knowledge Hub</a></p><p class="lead">A fictional, self-contained incident-response training environment. Before accessing the simulated workstation, please read and acknowledge the following rules.</p><div class="agreements"><label class="check"><input class="accept" type="checkbox"/><span><strong>Educational use only.</strong> This application does not grant permission to access or test any real system. All organisations, people, hosts, logs, messages, domains and security events are fictional.</span></label><label class="check"><input class="accept" type="checkbox"/><span><strong>Safe and lawful conduct.</strong> I will not enter real passwords, personally identifiable information, customer data or confidential business information. I understand real cyber actions require explicit authority and organisational procedures.</span></label><label class="check"><input class="accept" type="checkbox"/><span><strong>Evidence and legal limits.</strong> Simulated logs, hashes, chain-of-custody and scores are educational aids, not actual forensic proof, certification or legal advice. I will follow current organisational and regulatory guidance in real incidents.</span></label></div><div class="notice">All case activity remains in this browser; there is no login, telemetry or server submission. Export your progress regularly, especially on managed devices. Official reference links are optional and require an internet connection.</div><div class="row" style="margin-top:1rem;justify-content:space-between"><span class="small muted">Estio-branded educational simulation; not connected to live organisational systems.</span><button class="btn primary" id="accept" disabled>Accept and enter SOC →</button></div></div></div>`}
 function desktop(){let appButtons=APPS.map(([id,ico,name])=>`<button class="shortcut" data-act="open" data-app="${id}" title="Open ${name}"><span class="emoji">${ico}</span><span>${e(name)}</span></button>`).join('');root.innerHTML=`<div class="screen"><header class="top"><div class="brand"><img class="estio-brand" src="assets/estio-logo.png" alt="Estio logo"><div><strong>Northbridge SOC <span style="color:var(--pink)">3.2</span></strong><small>ESTIO · VIRTUAL ANALYST WORKSTATION</small></div></div><div class="topright"><span class="pill live">● SAFE SIMULATION</span><span class="pill" id="top-clock">${E.formatTime(m().minute)}</span><a class="btn small" href="knowledge/index.html">📖 Learn the process</a><button class="btn small" data-act="app-launcher">▦ Apps</button><button class="btn small" data-act="case-picker">📂 Cases</button><button class="btn small" data-act="settings">⚙ Display & data</button></div></header><main id="workarea" class="desktop"><div class="wall"></div><nav class="desktop-icons" aria-label="Workstation applications">${appButtons}</nav><div class="wall-note"><h1>Investigate.<br>Decide.<br>Recover.</h1><p>A practice SOC, built for real reasoning.</p></div><div id="window-layer"></div></main><footer class="taskbar"><button class="taskbar-app" data-act="open" data-app="brief">◈ Shift</button><div id="task-items" class="row"></div><span class="spacer"></span><button class="taskbar-app" data-act="report">⬇ Case file</button><span class="pill">${e(c().id.toUpperCase())}</span></footer></div><div id="overlay-host"></div>`;root.classList.toggle('lightmode',!!S.settings.light);document.body.classList.toggle('lightmode',!!S.settings.light);document.body.classList.toggle('reading-ruler',!!S.settings.ruler);document.documentElement.style.setProperty('--scale',S.settings.large?'1.13':'1')}
 function windows(){let layer=document.getElementById('window-layer');if(!layer)return;for(const node of [...layer.querySelectorAll('.window')]){const wid=node.id.replace('win-','');if(!ui.windows[wid]?.open)node.remove();}for(const [id,w] of Object.entries(ui.windows)){if(!w.open)continue;let node=document.getElementById('win-'+id);if(!node){node=document.createElement('section');node.className='window';node.id='win-'+id;node.setAttribute('role','region');node.setAttribute('aria-label',names[id].name);layer.appendChild(node)}node.style.zIndex=w.z;node.style.display=w.min?'none':'flex';node.classList.toggle('focused',w.z===ui.z);if(!w.setpos){node.style.left=(255+Object.keys(ui.windows).indexOf(id)*24)+'px';node.style.top=(36+Object.keys(ui.windows).indexOf(id)*22)+'px';w.setpos=true}node.innerHTML=`<header class="winbar" data-drag="${id}"><div class="wintitle"><span>${names[id].icon}</span><span>${e(names[id].name)}</span><small>— ${e(c().title)}</small></div><div class="window-controls"><button class="win-control" data-act="minimize" data-app="${id}" aria-label="Minimise ${e(names[id].name)}">−</button><button class="win-control" data-act="maximize" data-app="${id}" aria-label="Maximise ${e(names[id].name)}">□</button><button class="win-control" data-act="close" data-app="${id}" aria-label="Close ${e(names[id].name)}">×</button></div></header><div class="wincontent">${renderers[id]()}</div><footer class="winfooter">Simulated data only · independent ${id==='brief'?'mission':'tool'} state · ${e(E.formatTime(m().minute))}</footer>`}document.getElementById('task-items').innerHTML=Object.entries(ui.windows).filter(([id,w])=>w.open).map(([id,w])=>`<button class="taskbar-app ${w.z===ui.z&&!w.min?'active':''}" data-act="restore" data-app="${id}">${names[id].icon} ${e(names[id].name)}</button>`).join('');document.getElementById('top-clock').textContent=E.formatTime(m().minute)}
 function open(id){if(!renderers[id])return;if(!ui.windows[id])ui.windows[id]={open:true,min:false,z:++ui.z};else Object.assign(ui.windows[id],{open:true,min:false,z:++ui.z});windows()}
 function redraw(id){if(!id)return windows();let node=document.getElementById('win-'+id),w=ui.windows[id];if(node&&w?.open){let content=node.querySelector('.wincontent'),scroll=content?.scrollTop||0; if(content){content.innerHTML=renderers[id]();content.scrollTop=scroll;}}windowsTaskOnly()}
 function windowsTaskOnly(){let items=document.getElementById('task-items');if(items)items.innerHTML=Object.entries(ui.windows).filter(([,w])=>w.open).map(([id,w])=>`<button class="taskbar-app ${w.z===ui.z&&!w.min?'active':''}" data-act="restore" data-app="${id}">${names[id].icon} ${e(names[id].name)}</button>`).join('');let clk=document.getElementById('top-clock');if(clk)clk.textContent=E.formatTime(m().minute)}
 function refreshAll(){for(const id of Object.keys(ui.windows))redraw(id)}
 function toast(app,message,ok=true){ui.feedback[app]={message,ok};redraw(app)}
 function download(name,content,mime){let blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
 function overlay(html){document.getElementById('overlay-host').innerHTML=html||''}
 function confirmDlg(message,yes,label='Confirm change'){ui.pending=yes;overlay(`<div class="modal" role="dialog" aria-modal="true"><div class="modal-body"><h2>${e(label)}</h2><p>${e(message)}</p><div class="row">${btn('confirm','Yes, continue','danger')}${btn('cancel','Cancel')}</div></div></div>`)}
 function settings(){overlay(`<div class="modal" role="dialog" aria-modal="true" aria-label="Display and progress settings"><div class="modal-body"><div class="row" style="justify-content:space-between"><h2>Display & local progress</h2>${btn('cancel','× Close','small')}</div><label class="check"><input type="checkbox" data-setting="light" ${S.settings.light?'checked':''}/> <span>Light theme</span></label><label class="check"><input type="checkbox" data-setting="large" ${S.settings.large?'checked':''}/> <span>Larger text</span></label><label class="check"><input type="checkbox" data-setting="ruler" ${S.settings.ruler?'checked':''}/> <span>Reading ruler</span></label><hr class="divider"/><p class="muted small">Progress is saved to your current browser. Use exported JSON to move between devices or protect against managed-browser data clearing.</p><div class="row">${btn('backup','⬇ Export all progress','green')}${btn('import','⬆ Import progress')}${btn('report','⬇ Download case file')}</div><input type="file" id="import-file" accept="application/json,.json" hidden/><hr class="divider"/><div class="row">${btn('reset-case','↻ Reset selected case','danger small')}${btn('reset-all','⚠ Reset all local progress','danger small')}</div><p class="tiny muted">All resets require confirmation. The v2 Academy maintains separate progress.</p></div></div>`)}
 function launcher(){overlay(`<div class="modal" role="dialog" aria-modal="true" aria-label="Application launcher"><div class="modal-body"><div class="row" style="justify-content:space-between"><h2>Open analyst tool</h2>${btn('cancel','× Close','small')}</div><div class="grid2">${APPS.map(([id,ico,name])=>`<button class="asset" data-act="open-from-modal" data-app="${id}"><span>${ico} <strong>${e(name)}</strong></span><small>Open simulated application</small></button>`).join('')}</div></div></div>`)}
 function picker(){overlay(`<div class="modal" role="dialog" aria-modal="true" aria-label="Choose investigation"><div class="modal-body"><div class="row" style="justify-content:space-between"><h2>Choose your incident</h2>${btn('cancel','× Close','small')}</div><p class="muted">Each case has isolated progress. Change cases without wiping your other investigations.</p>${E.CASES.map(x=>{let steps=E.state.missions[x.id],total=steps?Object.values(steps.inspected).reduce((n,a)=>n+a.length,0):0;return `<div class="listitem"><div class="row"><strong>${x.icon} ${e(x.title)}</strong>${tagged(x.difficulty)}</div><p>${e(x.intro)}</p><p class="tiny muted">${e(x.tag)} · ${total} records inspected</p>${btn('choose-case',x.id===S.caseId?'Continue current case':'Open case','primary small',`data-id="${x.id}"`)}</div>`}).join('')}</div></div>`)}
 function dialogCustody(id){let p=m().preserved.find(p=>p.id===id);if(!p)return;overlay(`<div class="modal" role="dialog" aria-modal="true"><div class="modal-body"><h2>Record evidence transfer · ${e(id)}</h2><p>Current custodian: ${e(p.custody[p.custody.length-1].to)}</p><div class="field"><label>Transfer to</label><input id="custody-to" placeholder="Forensic analyst / evidence custodian"/></div><div class="field"><label>Purpose of transfer</label><textarea id="custody-purpose"></textarea></div><div class="row"><button class="btn primary" data-act="save-custody" data-id="${e(id)}">Record transfer</button>${btn('cancel','Cancel')}</div></div></div>`)}
 function rerenderWithRefresh(id){if(id)redraw(id);else refreshAll()}
 function closestWindow(el){return el.closest('.window')?.id.replace('win-','')||'brief'}
 async function execute(act,b){let app=closestWindow(b),id=b.dataset.id,tool=b.dataset.tool;switch(act){case'open':open(b.dataset.app);break;case'open-from-modal':overlay('');open(b.dataset.app);break;case'app-launcher':launcher();break;case'close':{const wid=b.dataset.app;const x=ui.windows[wid];if(x){x.open=false;x.min=false;x.setpos=false;}document.getElementById('win-'+wid)?.remove();windows();break}case'minimize':ui.windows[b.dataset.app].min=true;windows();break;case'restore':{let x=ui.windows[b.dataset.app];x.min=false;x.z=++ui.z;windows();break}case'maximize':{let w=document.getElementById('win-'+b.dataset.app);if(w.dataset.max==='yes'){w.style.top='36px';w.style.left='255px';w.style.width='min(930px,calc(100% - 265px))';w.style.height='590px';w.dataset.max='no';}else{w.style.left='6px';w.style.top='4px';w.style.width='calc(100% - 12px)';w.style.height='calc(100% - 10px)';w.dataset.max='yes';}break}
 case'lab-select':{m().labState.selected=id;delete ui.feedback.practice;E.save();redraw('practice');break}
 case'lab-hint':{let t=m().labState.selected,st=m().labState;st.hints[t]=Math.min(3,(st.hints[t]||0)+1);E.save();redraw('practice');break}
 case'lab-task-reset':{let task=m().labState.selected;confirmDlg('Reset this assignment\'s worksheet, hints and completion badge? Other exercises, evidence and tool state will be kept. You will need to run the terminal steps again.',()=>{let st=m().labState;delete st.finished[task];delete st.notes[task];delete st.hints[task];st.baselines[task]=m().terminal.length;delete ui.feedback.practice;E.save();redraw('practice')},'Reset only this assignment');break}
 case'lab-check':{let st=m().labState,task=(window.NBSIM_LABS[c().id]||[]).find(t=>t.id===st.selected);if(!task)break;const baseline=Math.min(st.baselines[task.id]||0,m().terminal.length);const checks=task.checks.map(ch=>{const [type,description,a,b]=ch;switch(type){case'terminal':return m().terminal.slice(baseline).some(h=>new RegExp(a,'i').test(h.cmd.trim())&&(!b||h.host===b));case'inspect':return (m().inspected[a]||[]).includes(b);case'preserve':return m().preserved.some(r=>r.id===a);case'action':return m().actions.some(r=>r.control===a&&r.asset===b);case'ticket':return m().tickets.length>0;case'comms':return m().comms.length>0;case'recovery':return m().validation.length>0;case'late':return m().late;case'reflection':return (st.notes[task.id]||'').trim().length>=40;default:return false;}});let total=checks.filter(Boolean).length;let done=checks.every(Boolean);st.finished[task.id]=done;ui.feedback.practice={task:task.id,ok:done,message:done?'Mission completed. Your documented work is now included in the case file. You can move on or retry this mission.':`${total}/${checks.length} requirements evidenced. Still to complete: `+checks.map((x,i)=>x?'':task.checks[i][1]).filter(Boolean).join('; ')};E.save();redraw('practice');redraw('brief');break}
 case'case-picker':picker();break;case'choose-case':E.setCase(id);ui.selected={};ui.filter={};ui.windows={};ui.feedback={};overlay('');desktop();open('brief');break;case'settings':settings();break;case'cancel':ui.pending=null;overlay('');break;case'confirm':{let task=ui.pending;ui.pending=null;overlay('');if(task)task();break}
 case'inspect':{let kind=b.dataset.kind;let record=E.getRecord(id);if(record){E.inspect(kind==='eventviewer'?'siem':kind,id);setSel(kind,id);redraw(kind);redraw('brief');}break}
 case'packet-select':E.inspect('network',id);setSel('packet',id);redraw('packet');break;
 case'add-timeline':{let result=E.timelineAdd(document.getElementById('timeline-reference')?.value||'',document.getElementById('timeline-note')?.value||'');toast('timeline',result.message,result.ok);break}
 case'flag':E.flag(id);toast(app,'Flagged '+id+' for consideration in the Evidence Locker.');break;case'unflag':E.unflag(id);redraw('locker');break;case'choose-evidence':setSel('evId',id);redraw('locker');break;
 case'preserve':{let fields={purpose:document.getElementById('ev-purpose')?.value||'',handler:document.getElementById('ev-handler')?.value||'',method:document.getElementById('ev-method')?.value||''};ui.lockForm=fields;let result=await E.preserve(sel('evId'),fields);toast('locker',result.message,result.ok);redraw('brief');break}
 case'verify':{let v=await E.verify(id);toast('locker',v?.same?'Integrity verified: retained snapshot matches its original SHA-256 digest.':'INTEGRITY ALERT: retained lab copy no longer matches its original digest.',!!v?.same);break}
 case'mutate':confirmDlg('Alter the retained simulated LAB COPY of '+id+'? The mismatch will be visible on the next integrity check. Original source records are not altered.',()=>{E.mutate(id);toast('locker','LAB COPY modified. Run Verify Hash to detect the change.');},'Simulated evidence tampering');break;
 case'custody':dialogCustody(id);break;case'save-custody':{let to=document.getElementById('custody-to')?.value.trim(),purpose=document.getElementById('custody-purpose')?.value.trim();if(!to||!purpose){alert('Please record both a recipient and reason.');break}E.shiftEvidence(id,to,purpose);overlay('');toast('locker','Custody transfer recorded for '+id+'.');break}
 case'save-ticket':{let result=E.ticket(document.getElementById('ticket-class')?.value,document.getElementById('ticket-priority')?.value,document.getElementById('ticket-owner')?.value||'',document.getElementById('ticket-reason')?.value||'');toast('tickets',result.message,result.ok);redraw('brief');break}
 case'send-comms':{let result=E.communicate(document.getElementById('comms-recipient')?.value,document.getElementById('comms-body')?.value||'',document.getElementById('comms-approval')?.value||'');toast('comms',result.message,result.ok);redraw('brief');break}
 case'apply-response':{let chosen=f('responseAsset')||c().assets[0].id,control=f('responseControl')||'monitor',authority=document.getElementById('response-authority')?.value||'',reason=document.getElementById('response-reason')?.value||'',pid=document.getElementById('response-pid')?.value||'';ui.responseForm={approved:authority,reason};let result=E.response(control,chosen,authority,reason,pid);toast('response',result.message,result.ok);refreshAll();break}
 case'apply-recovery':{let authority=document.getElementById('recovery-authority')?.value||'',reason=document.getElementById('recovery-reason')?.value||'';ui.recoveryForm.approved=authority;ui.recoveryForm.reason=reason;let result=E.recovery(f('recoveryOption')||(c().recovery==='restore'?'safe':'verify'),[0,1,2].map(i=>!!ui.recoveryForm['check'+i]),authority,reason);toast('recovery',result.message,result.ok);refreshAll();break}
 case'next-hint':{let tab=sel('helpTab')||'siem';ui.hint[tab]=Math.min(2,(ui.hint[tab]||0)+1);redraw('help');break}
 case'terminal-help':open('help');setSel('helpTab','terminal');redraw('help');break;
 case'asset-info':{let a=E.asset(id);toast('map',a.id+' · '+a.service+' · '+E.status(a.id));break}
 case'advance':E.clock(5);refreshAll();break;case'refresh':redraw(app);break;
 case'report':download('Northbridge_'+c().id+'_casefile.html',E.report(),'text/html;charset=utf-8');break;
 case'backup':download('Northbridge_SOC_v3_progress.json',E.exportJSON(),'application/json');break;
 case'import':document.getElementById('import-file')?.click();break;
 case'reset-tool':confirmDlg('Reset only the '+names[tool].name+' activity in the current case? Other tools, case notes and the other cases stay available. If you reset response actions, active simulated controls are removed from this case.',()=>{E.resetTool(tool);delete ui.feedback[tool];if(tool==='siem'||tool==='endpoint'||tool==='network'||tool==='mail'||tool==='files')setSel(tool,'');refreshAll()},'Reset this exercise');break;
 case'reset-case':confirmDlg('Clear all tools, notes, decisions, and the clock ONLY for '+c().title+'? Other cases and the original Academy are not touched.',()=>{E.resetMission(S.caseId);ui.selected={};ui.filter={};ui.feedback={};ui.recoveryForm={};ui.responseForm={};ui.lockForm={};overlay('');refreshAll()},'Reset this investigation');break;
 case'reset-all':confirmDlg('Erase all FOUR v3 investigations, settings, notes, saved case files and consent from this browser? This does not affect v2 Academy progress.',()=>{try{localStorage.removeItem(E.KEY)}catch{}location.reload()},'Delete all v3 local progress');break;
 }}
 function beginSession(){
  const qp=new URLSearchParams(location.search),caseId=qp.get('case'),taskId=qp.get('task'),tool=qp.get('tool');
  const fromGuide=!!caseId&&E.CASES.some(x=>x.id===caseId);
  if(fromGuide){E.setCase(caseId); const target=window.NBSIM_LABS?.[caseId]?.find(t=>t.id===taskId); if(target){const record=m();if(!record.labState)record.labState={selected:taskId,finished:{},notes:{},hints:{},baselines:{}}; record.labState.selected=taskId;E.save();}}
  desktop();open(fromGuide?'practice':'brief');
  if(fromGuide&&tool&&tool!=='practice'&&renderers[tool])open(tool);
 }
 function startup(){if(!S.consent){root.innerHTML=legal();root.addEventListener('change',function listener(ev){if(!ev.target.classList.contains('accept'))return;let all=[...root.querySelectorAll('.accept')];root.querySelector('#accept').disabled=!all.every(x=>x.checked)});root.addEventListener('click',ev=>{if(ev.target.id==='accept'){if([...root.querySelectorAll('.accept')].every(x=>x.checked)){S.consent=true;E.save();beginSession();if(!new URLSearchParams(location.search).has('case'))open('help')}}});return}beginSession();}
 root.addEventListener('click',ev=>{let b=ev.target.closest('[data-act]');if(!b)return;ev.preventDefault();execute(b.dataset.act,b).catch(err=>{console.error(err);toast(closestWindow(b),'Unexpected interface problem. '+err.message,false)})});
 root.addEventListener('change',ev=>{let t=ev.target;if(t.dataset.filter){ui.filter[t.dataset.filter]=t.value;redraw(closestWindow(t));}if(t.dataset.journal){E.saveJournal(t.dataset.journal,t.value);redraw('brief');}if(t.dataset.recoveryCheck!==undefined){ui.recoveryForm['check'+t.dataset.recoveryCheck]=t.checked;}if(t.dataset.setting){S.settings[t.dataset.setting]=t.checked;E.save();let was=!!S.consent;desktop();if(was){open('brief');settings()}}if(t.id==='help-tab'){setSel('helpTab',t.value);redraw('help')}if(t.id==='import-file'&&t.files?.[0]){let file=t.files[0];file.text().then(str=>{try{E.importJSON(str);ui.windows={};overlay('');desktop();open('brief')}catch(err){alert('Import failed: '+err.message)}})}});
 root.addEventListener('input',ev=>{let t=ev.target;if(t.dataset.filter)ui.filter[t.dataset.filter]=t.value;if(t.dataset.journal)E.saveJournal(t.dataset.journal,t.value);if(t.id==='ev-purpose')ui.lockForm.purpose=t.value;if(t.id==='ev-handler')ui.lockForm.handler=t.value;if(t.id==='ev-method')ui.lockForm.method=t.value;if(t.id==='response-reason')ui.responseForm.reason=t.value;if(t.id==='response-authority')ui.responseForm.approved=t.value;if(t.id==='recovery-reason')ui.recoveryForm.reason=t.value;if(t.id==='recovery-authority')ui.recoveryForm.approved=t.value;if(t.dataset.labNote){let st=m().labState;st.notes[t.dataset.labNote]=t.value;E.save();}});
 root.addEventListener('submit',ev=>{let session=ev.target.id==='lab-terminal-form'?'practice':ev.target.dataset.terminalForm;if(!session)return;ev.preventDefault();let input=ev.target.querySelector('input'),cmd=input.value.trim();if(!cmd)return;E.runCommand(cmd,session).then(()=>{redraw(session);let consoleNode=document.getElementById(session==='practice'?'lab-console':'console-'+session);if(consoleNode)consoleNode.scrollTop=consoleNode.scrollHeight;document.querySelector(session==='practice'?'#lab-command':`[data-terminal-input=\"${session}\"]`)?.focus()}).catch(x=>console.error(x))});
 let drag=null;root.addEventListener('pointerdown',ev=>{let hdr=ev.target.closest('[data-drag]');if(!hdr||ev.target.closest('button')||window.innerWidth<950)return;let id=hdr.dataset.drag,node=document.getElementById('win-'+id);if(!node)return;ui.windows[id].z=++ui.z;node.style.zIndex=ui.z;let rect=node.getBoundingClientRect();drag={id,startX:ev.clientX,startY:ev.clientY,left:rect.left,top:rect.top,ptr:ev.pointerId};try{hdr.setPointerCapture(ev.pointerId)}catch{};});root.addEventListener('pointermove',ev=>{if(!drag)return;let node=document.getElementById('win-'+drag.id);if(!node)return;let x=Math.max(0,Math.min(window.innerWidth-100,drag.left+ev.clientX-drag.startX)),y=Math.max(0,Math.min(500,drag.top-65+ev.clientY-drag.startY));node.style.left=x+'px';node.style.top=y+'px';});root.addEventListener('pointerup',()=>drag=null);root.addEventListener('pointercancel',()=>drag=null);
 root.addEventListener('pointerdown',ev=>{let win=ev.target.closest('.window');if(win){let id=win.id.replace('win-','');if(ui.windows[id]){ui.windows[id].z=++ui.z;win.style.zIndex=ui.z;windowsTaskOnly()}}});
 startup();
})();
